(5493586, 792149, 36132, '<td valign="top">Oh my days, this girl is absolutely fantastic.. !!</td>', 'Oh my days, this girl is absolutely fantastic.. !!', '2009-05-20 06:06:35.000000', NULL, 1),
(5493590, 790895, 33736, '<td valign="top">The blurred hand, the background texture, and those two elements showing along the front of her arm (one looks like a Penny, the other her gown) take away from her beautiful face and hair.</td>', 'The blurred hand, the background texture, and those two elements showing along the front of her arm (one looks like a Penny, the other her gown) take away from her beautiful face and hair.', '2009-05-20 06:08:49.000000', NULL, 1),
