(5493606, 792338, 33736, '<td valign="top">The white dot (might have chosen a different color for this one) in the corner of her left eye and the shine of the ring are a bit distracting; otherwise a wonderful portrait.</td>', 'The white dot (might have chosen a different color for this one) in the corner of her left eye and the shine of the ring are a bit distracting; otherwise a wonderful portrait.', '2009-05-20 06:20:26.000000', NULL, 1),
(5493608, 792266, 99506, '<td valign="top">Great shot but that shelf is very distracting</td>', 'Great shot but that shelf is very distracting', '2009-05-20 06:21:00.000000', NULL, 1),
