(5493789, 791211, 106965, '<td valign="top">beautiful</td>', 'beautiful', '2009-05-20 09:31:54.000000', NULL, 1),
(5493790, 791294, 106965, '<td valign="top">My favorite so far. 9</td>', 'My favorite so far. 9', '2009-05-20 09:34:57.000000', NULL, 1),
(5493812, 791993, 30049, '<td valign="top">Wonderful lighting, sharp, and professionally shot.  Well done!</td>', 'Wonderful lighting, sharp, and professionally shot.  Well done!', '2009-05-20 09:50:40.000000', NULL, 1),
(5493814, 791844, 30049, '<td valign="top">This pose is perfect, as is the comp.  Focus on the eyes could be stronger, but still a good piece of work.  Compared against others thus far it''s a 9.  Good luck.</td>', 'This pose is perfect, as is the comp.  Focus on the eyes could be stronger, but still a good piece of work.  Compared against others thus far it''s a 9.  Good luck.', '2009-05-20 09:51:34.000000', NULL, 1),
