(5496981, 792338, 58728, '<td valign="top">This photo is stunning.  Beautifully executed.</td>', 'This photo is stunning.  Beautifully executed.', '2009-05-23 00:49:11.000000', NULL, 1),
(5496983, 792266, 106576, '<td valign="top">Besides her being beautiful and "glamourous", I like the lighting, the offset, rule of thirds use, and I even like the blurred background! I don''t know why I like the background but it just gives you something there, sort of pointing out her beauty vs. it''s Not!  Just my thoughts!<br/>thanks for showing us, and I am not a glamour kind of shooter so take it with a grain of salt!</td>', 'Besides her being beautiful and "glamourous", I like the lighting, the offset, rule of thirds use, and I even like the blurred background! I don''t know why I like the background but it just gives you something there, sort of pointing out her beauty vs. it''s Not!  Just my thoughts!thanks for showing us, and I am not a glamour kind of shooter so take it with a grain of salt!', '2009-05-23 00:50:56.000000', NULL, 1),
(5496985, 792261, 106576, '<td valign="top">hmmm, a really pretty ring, and a beautiful backdrop in this rose (very creative!!), but your title doesn''t match, at least my view, of the photo!<br/>I would have liked to see some amazing sparkle from the ring. <br/>Maybe it''s just me! Shoot this again with a star filter or some intense light, or F22(?) and I think it becomes an amazing shot! <br/>But it is still pretty and I love your creativity, just not the photo with the title.</td>', 'hmmm, a really pretty ring, and a beautiful backdrop in this rose (very creative!!), but your title doesn''t match, at least my view, of the photo!I would have liked to see some amazing sparkle from the ring. Maybe it''s just me! Shoot this again with a star filter or some intense light, or F22(?) and I think it becomes an amazing shot! But it is still pretty and I love your creativity, just not the photo with the title.', '2009-05-23 00:55:33.000000', NULL, 1),
(5496987, 791324, 106576, '<td valign="top">Glamourous, and it''s not even a lady!<br/> <br/>Indeed very pretty, glad you could find one with all the feathers in good shape; mine always are damaged.<br/>I am being very critical here and I admit it but I would like to see the brightness and contrast kicked up here. I am new so not sure how all tht fits with contest, just my thoughts! Still very nice!<br/>Thanks for showing him to us!</td>', 'Glamourous, and it''s not even a lady! Indeed very pretty, glad you could find one with all the feathers in good shape; mine always are damaged.I am being very critical here and I admit it but I would like to see the brightness and contrast kicked up here. I am new so not sure how all tht fits with contest, just my thoughts! Still very nice!Thanks for showing him to us!', '2009-05-23 00:59:15.000000', NULL, 1),
(5497090, 791382, 100773, '<td valign="top">It''s a good capture. Must be hard photographing dancers, haven''t tried it yet. Maybe the focus is a bit soft, or slightly misplaced, but that''s nitpicking. In terms of the challenge, I don''t see that much of glamour. If it had been a performance instead of practice, then maybe one could''ve said it was glamour. But still a good shot.</td>', 'It''s a good capture. Must be hard photographing dancers, haven''t tried it yet. Maybe the focus is a bit soft, or slightly misplaced, but that''s nitpicking. In terms of the challenge, I don''t see that much of glamour. If it had been a performance instead of practice, then maybe one could''ve said it was glamour. But still a good shot.', '2009-05-23 06:50:23.000000', NULL, 1),
(5497091, 790993, 100773, '<td valign="top">You should have entered this in the free study, because this is a very beautifull shot that I think will recieve very low votes in this challenge. Personally, except from the good lighting, I don''t see any typical glamourous. Sorry</td>', 'You should have entered this in the free study, because this is a very beautifull shot that I think will recieve very low votes in this challenge. Personally, except from the good lighting, I don''t see any typical glamourous. Sorry', '2009-05-23 06:56:11.000000', NULL, 1),
(5497092, 791728, 100773, '<td valign="top">You got something there, but the picture is to small.</td>', 'You got something there, but the picture is to small.', '2009-05-23 06:57:10.000000', NULL, 1),
(5497093, 792207, 100773, '<td valign="top">The only glamour I see in this picture must be some sort of metaphor if the women in Troy looked glamourous. Interesting picture, and I like the angle, but I don''t think this meets the challenge criteria.</td>', 'The only glamour I see in this picture must be some sort of metaphor if the women in Troy looked glamourous. Interesting picture, and I like the angle, but I don''t think this meets the challenge criteria.', '2009-05-23 06:59:41.000000', NULL, 1),
(5497095, 792322, 100773, '<td valign="top">I don''t understand why there''s so much grain in her hair. Other than that, the depth of field is very good, and I find this a very good sample of glamour.</td>', 'I don''t understand why there''s so much grain in her hair. Other than that, the depth of field is very good, and I find this a very good sample of glamour.', '2009-05-23 07:04:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5497097, 790895, 100773, '<td valign="top">Maybe "implied nudity" would''ve added a little extra to this, but once you find a model like this you might wanna ask her to pose fake nude. I find this photo quite stunning. And the veil is a good detail, I think. I can''t figure out if it just hangs there, or if she weares it so she would look like a bride. But aside from that, beautifull skin tones, the pose is good, good job! Her eyes though, if possible, I think they would''ve looked even better if the blue color didn''t look slightly saturated. 7</td>', 'Maybe "implied nudity" would''ve added a little extra to this, but once you find a model like this you might wanna ask her to pose fake nude. I find this photo quite stunning. And the veil is a good detail, I think. I can''t figure out if it just hangs there, or if she weares it so she would look like a bride. But aside from that, beautifull skin tones, the pose is good, good job! Her eyes though, if possible, I think they would''ve looked even better if the blue color didn''t look slightly saturated. 7', '2009-05-23 07:13:03.000000', NULL, 1),
(5497099, 792196, 100773, '<td valign="top">I suppose this is glamourous, I wouldn''t know because I only have read about live models in glamour photography. But in terms of color and lighting, the criteria is met. So I guess this is a picture that conveys glamour. 7</td>', 'I suppose this is glamourous, I wouldn''t know because I only have read about live models in glamour photography. But in terms of color and lighting, the criteria is met. So I guess this is a picture that conveys glamour. 7', '2009-05-23 07:18:54.000000', NULL, 1),
(5497101, 791282, 100773, '<td valign="top">The only bad thing about this is the size. I wish it would''ve been larger! Very nice photo, and a perfect display of glamour in my oppinion.</td>', 'The only bad thing about this is the size. I wish it would''ve been larger! Very nice photo, and a perfect display of glamour in my oppinion.', '2009-05-23 07:20:18.000000', NULL, 1),
(5497102, 792261, 100773, '<td valign="top">The idea is kinda good, but the light that strikes the ring (or whatever it is) is a little to harsh for my taste.</td>', 'The idea is kinda good, but the light that strikes the ring (or whatever it is) is a little to harsh for my taste.', '2009-05-23 07:21:23.000000', NULL, 1),
(5497103, 792118, 100773, '<td valign="top">Great black and white performance, maybe a bit to great. It kinda looks like half of her "behind" is removed, and that''s a little unfortunate in this challenge. Unique idea, I haven''t seen anything like this yet in my voting. All in all a good picture!</td>', 'Great black and white performance, maybe a bit to great. It kinda looks like half of her "behind" is removed, and that''s a little unfortunate in this challenge. Unique idea, I haven''t seen anything like this yet in my voting. All in all a good picture!', '2009-05-23 07:23:52.000000', NULL, 1),
(5497105, 792279, 100773, '<td valign="top">Captured in the correct moment, to bad the focus is misplaced. I don''t see glamourous side of this photo all that much either, so not a very high score from me.</td>', 'Captured in the correct moment, to bad the focus is misplaced. I don''t see glamourous side of this photo all that much either, so not a very high score from me.', '2009-05-23 07:25:27.000000', NULL, 1),
(5497106, 792037, 100773, '<td valign="top">I would like to see more contrast. The kids "blends" in to the background, not entirely, but they''re on their way. There''s also some grain here, but that''s just charming had the background been smoother.</td>', 'I would like to see more contrast. The kids "blends" in to the background, not entirely, but they''re on their way. There''s also some grain here, but that''s just charming had the background been smoother.', '2009-05-23 07:30:01.000000', NULL, 1),
(5497110, 792136, 100773, '<td valign="top">Wrong challenge. You should''ve put this in the free study. Fixed the strange haloish thing around the hair, and entered it in the free study where it would''ve scored very high.</td>', 'Wrong challenge. You should''ve put this in the free study. Fixed the strange haloish thing around the hair, and entered it in the free study where it would''ve scored very high.', '2009-05-23 07:32:54.000000', NULL, 1),
(5497112, 791324, 100773, '<td valign="top">Doubt you can find any animal or bird more glamourous than this. Nice picture and entry. In terms of presentation, I think some added contrast could improved it a tad.</td>', 'Doubt you can find any animal or bird more glamourous than this. Nice picture and entry. In terms of presentation, I think some added contrast could improved it a tad.', '2009-05-23 07:34:33.000000', NULL, 1),
(5497313, 791360, 15711, '<td valign="top">She''s lovely.  Wish the background wasn''t so close and so wrinkled.</td>', 'She''s lovely.  Wish the background wasn''t so close and so wrinkled.', '2009-05-23 11:46:25.000000', NULL, 1),
(5497314, 791922, 15711, '<td valign="top">Did you mean to put this in grunge?</td>', 'Did you mean to put this in grunge?', '2009-05-23 11:46:52.000000', NULL, 1),
(5497315, 792192, 15711, '<td valign="top">This is lovely.  Reminds me of an old movie star shot by Richard Avedon.  The single eye.  NICE.</td>', 'This is lovely.  Reminds me of an old movie star shot by Richard Avedon.  The single eye.  NICE.', '2009-05-23 11:47:29.000000', NULL, 1),
(5497317, 792136, 15711, '<td valign="top">Grunge??</td>', 'Grunge??', '2009-05-23 11:48:10.000000', NULL, 1),
