(5497729, 792339, 70036, '<td valign="top">Superb.  Composition and lighting are excellent.</td>', 'Superb.  Composition and lighting are excellent.', '2009-05-23 21:14:07.000000', NULL, 1),
(5497730, 791867, 70036, '<td valign="top">Wonderful shot.  Tells a story. Composition could possibly use some help to make this a 10.  I would have cropped the sky a bit and tried to highlight her eyes.  Possibly even cropping out the girl on the left to put Mom in the thirds.    But this picture really struck me right away.  It has great impact.</td>', 'Wonderful shot.  Tells a story. Composition could possibly use some help to make this a 10.  I would have cropped the sky a bit and tried to highlight her eyes.  Possibly even cropping out the girl on the left to put Mom in the thirds.    But this picture really struck me right away.  It has great impact.', '2009-05-23 21:16:44.000000', NULL, 1),
(5497781, 792339, 104955, '<td valign="top">Good color combos. Great lighting, esp. umbrella. The eyes really pop.</td>', 'Good color combos. Great lighting, esp. umbrella. The eyes really pop.', '2009-05-23 22:21:34.000000', NULL, 1),
